     1→// ============================================================================
     2→// FreeLang Query 모듈 - SQL-like 쿼리 실행 엔진
     3→// ============================================================================
     4→// 목표: schema.fl 기반 테이블에서 WHERE/ORDER BY/LIMIT/집계 쿼리 실행
     5→// 원리:
     6→//   1. WhereClause: 컬럼 인덱스 + 연산자 + 비교값
     7→//   2. query_execute: 전체 행 순회 → 조건 평가 → 정렬 → 페이징
     8→//   3. 집계: COUNT/SUM/MAX
     9→// 구조:
    10→//   - 상수 정의 (연산자, 집계 타입)
    11→//   - WhereClause, OrderBy, Query, QueryResult 구조체
    12→//   - 쿼리 빌더 함수 (체이닝 스타일)
    13→//   - query_execute 실행 엔진
    14→// ============================================================================
    15→
    16→module query {
    17→    // === 비교 연산자 ===
    18→    const OP_EQ:   i32 = 1;   // ==
    19→    const OP_NE:   i32 = 2;   // !=
    20→    const OP_GT:   i32 = 3;   // >
    21→    const OP_LT:   i32 = 4;   // <
    22→    const OP_GE:   i32 = 5;   // >=
    23→    const OP_LE:   i32 = 6;   // <=
    24→    const OP_LIKE: i32 = 7;   // 접두어 일치 (str_starts_with)
    25→
    26→    // === 집계 타입 ===
    27→    const AGG_NONE:  i32 = 0;
    28→    const AGG_COUNT: i32 = 1;
    29→    const AGG_SUM:   i32 = 2;
    30→    const AGG_MAX:   i32 = 3;
    31→    const AGG_MIN:   i32 = 4;
    32→
    33→    // === 제한값 ===
    34→    const MAX_WHERE: i32 = 8;
    35→    const MAX_RESULT_ROWS: i32 = 1024;
    36→
    37→    // === 에러 코드 ===
    38→    const QUERY_OK:         i32 = 0;
    39→    const QUERY_ERR_TABLE:  i32 = 10;
    40→    const QUERY_ERR_COL:    i32 = 11;
    41→    const QUERY_ERR_EMPTY:  i32 = 12;
    42→
    43→    // === 데이터 구조체 ===
    44→
    45→    struct WhereClause {
    46→        col_idx:  i32;
    47→        op:       i32;
    48→        int_val:  i64;
    49→        str_val:  string;
    50→        is_str:   bool;   // true이면 str_val 사용, false이면 int_val 사용
    51→    }
    52→
    53→    struct OrderBy {
    54→        col_idx: i32;
    55→        asc:     bool;
    56→        is_str:  bool;   // 문자열 정렬 여부
    57→    }
    58→
    59→    struct Query {
    60→        // 대상 테이블 (포인터 대신 복사 — FreeLang 제약)
    61→        table_ptr:   i32;      // 전역 테이블 인덱스 (간단화)
    62→        wheres:      [WhereClause];
    63→        where_count: i32;
    64→        order_by:    OrderBy;
    65→        has_order:   bool;
    66→        limit:       i32;
    67→        offset:      i32;
    68→        agg_type:    i32;
    69→        agg_col:     i32;
    70→    }
    71→
    72→    struct QueryResult {
    73→        // 결과 행 인덱스 (schema.Table의 row_idx)
    74→        row_indices: [i32];
    75→        row_count:   i32;
    76→        agg_value:   i64;
    77→        error_code:  i32;
    78→    }
    79→
    80→    // === 쿼리 실행 (핵심) ===
    81→    // schema.Table을 직접 받아서 처리
    82→
    83→    func query_table(t: schema.Table) -> Query {
    84→        return Query{
    85→            table_ptr:   0,
    86→            wheres:      make([WhereClause], MAX_WHERE),
    87→            where_count: 0,
    88→            order_by:    OrderBy{ col_idx: 0, asc: true, is_str: false },
    89→            has_order:   false,
    90→            limit:       MAX_RESULT_ROWS,
    91→            offset:      0,
    92→            agg_type:    AGG_NONE,
    93→            agg_col:     0,
    94→        };
    95→    }
    96→
    97→    // WHERE int 조건 추가
    98→    func (q: *Query) where_int(col_idx: i32, op: i32, val: i64) -> bool {
    99→        if q.where_count >= MAX_WHERE {
   100→            return false;
   101→        }
   102→        q.wheres[q.where_count] = WhereClause{
   103→            col_idx: col_idx,
   104→            op:      op,
   105→            int_val: val,
   106→            str_val: "",
   107→            is_str:  false,
   108→        };
   109→        q.where_count = q.where_count + 1;
   110→        return true;
   111→    }
   112→
   113→    // WHERE str 조건 추가
   114→    func (q: *Query) where_str(col_idx: i32, op: i32, val: string) -> bool {
   115→        if q.where_count >= MAX_WHERE {
   116→            return false;
   117→        }
   118→        q.wheres[q.where_count] = WhereClause{
   119→            col_idx: col_idx,
   120→            op:      op,
   121→            int_val: 0,
   122→            str_val: val,
   123→            is_str:  true,
   124→        };
   125→        q.where_count = q.where_count + 1;
   126→        return true;
   127→    }
   128→
   129→    // ORDER BY 설정
   130→    func (q: *Query) order_by_int(col_idx: i32, asc: bool) {
   131→        q.order_by = OrderBy{ col_idx: col_idx, asc: asc, is_str: false };
   132→        q.has_order = true;
   133→    }
   134→
   135→    func (q: *Query) order_by_str(col_idx: i32, asc: bool) {
   136→        q.order_by = OrderBy{ col_idx: col_idx, asc: asc, is_str: true };
   137→        q.has_order = true;
   138→    }
   139→
   140→    // LIMIT/OFFSET 설정
   141→    func (q: *Query) set_limit(limit: i32) {
   142→        q.limit = limit;
   143→    }
   144→
   145→    func (q: *Query) set_offset(offset: i32) {
   146→        q.offset = offset;
   147→    }
   148→
   149→    // 집계 설정
   150→    func (q: *Query) set_aggregate(agg_type: i32, col_idx: i32) {
   151→        q.agg_type = agg_type;
   152→        q.agg_col = col_idx;
   153→    }
   154→
   155→    // === 조건 평가 함수 ===
   156→
   157→    @inline
   158→    func eval_int_op(actual: i64, op: i32, expected: i64) -> bool {
   159→        if op == OP_EQ  { return actual == expected; }
   160→        if op == OP_NE  { return actual != expected; }
   161→        if op == OP_GT  { return actual > expected; }
   162→        if op == OP_LT  { return actual < expected; }
   163→        if op == OP_GE  { return actual >= expected; }
   164→        if op == OP_LE  { return actual <= expected; }
   165→        return false;
   166→    }
   167→
   168→    @inline
   169→    func eval_str_op(actual: string, op: i32, expected: string) -> bool {
   170→        if op == OP_EQ   { return actual == expected; }
   171→        if op == OP_NE   { return actual != expected; }
   172→        if op == OP_LIKE {
   173→            // 접두어 일치 (str_starts_with 시뮬레이션)
   174→            let exp_len = len(expected);
   175→            let act_len = len(actual);
   176→            if exp_len > act_len {
   177→                return false;
   178→            }
   179→            let i = 0;
   180→            for i = 0; i < exp_len; i = i + 1 {
   181→                if char_at(actual, i) != char_at(expected, i) {
   182→                    return false;
   183→                }
   184→            }
   185→            return true;
   186→        }
   187→        return false;
   188→    }
   189→
   190→    // WHERE 절 평가 (AND 연결)
   191→    func eval_where(t: schema.Table, row_idx: i32, wheres: [WhereClause], where_count: i32) -> bool {
   192→        let i = 0;
   193→        for i = 0; i < where_count; i = i + 1 {
   194→            let w = wheres[i];
   195→            let col_idx = w.col_idx;
   196→            if col_idx < 0 || col_idx >= t.schema.col_count {
   197→                return false;
   198→            }
   199→            let col_type = t.schema.col_defs[col_idx].col_type;
   200→
   201→            if col_type == schema.COL_TYPE_INT {
   202→                let actual = t.get_int_val(row_idx, col_idx);
   203→                if !eval_int_op(actual, w.op, w.int_val) {
   204→                    return false;
   205→                }
   206→            } else if col_type == schema.COL_TYPE_STR {
   207→                let actual = t.get_str_val(row_idx, col_idx);
   208→                if !eval_str_op(actual, w.op, w.str_val) {
   209→                    return false;
   210→                }
   211→            } else if col_type == schema.COL_TYPE_BOOL {
   212→                let actual_bool = t.get_bool_val(row_idx, col_idx);
   213→                let actual_i64 = if actual_bool { 1 } else { 0 };
   214→                if !eval_int_op(actual_i64, w.op, w.int_val) {
   215→                    return false;
   216→                }
   217→            }
   218→        }
   219→        return true;
   220→    }
   221→
   222→    // === 정렬 (삽입 정렬) ===
   223→
   224→    func sort_by_int(t: schema.Table, indices: [i32], count: i32, col_idx: i32, asc: bool) {
   225→        let i = 1;
   226→        for i = 1; i < count; i = i + 1 {
   227→            let key_idx = indices[i];
   228→            let key_val = t.get_int_val(key_idx, col_idx);
   229→            let j = i - 1;
   230→
   231→            for j >= 0 {
   232→                let cmp_val = t.get_int_val(indices[j], col_idx);
   233→                let should_swap = if asc { cmp_val > key_val } else { cmp_val < key_val };
   234→                if !should_swap {
   235→                    break;
   236→                }
   237→                indices[j + 1] = indices[j];
   238→                j = j - 1;
   239→            }
   240→            indices[j + 1] = key_idx;
   241→        }
   242→    }
   243→
   244→    func sort_by_str(t: schema.Table, indices: [i32], count: i32, col_idx: i32, asc: bool) {
   245→        let i = 1;
   246→        for i = 1; i < count; i = i + 1 {
   247→            let key_idx = indices[i];
   248→            let key_val = t.get_str_val(key_idx, col_idx);
   249→            let j = i - 1;
   250→
   251→            for j >= 0 {
   252→                let cmp_val = t.get_str_val(indices[j], col_idx);
   253→                // 문자열 비교: 첫 글자만 (간단화)
   254→                let should_swap = false;
   255→                if len(cmp_val) > 0 && len(key_val) > 0 {
   256→                    if asc {
   257→                        should_swap = char_at(cmp_val, 0) > char_at(key_val, 0);
   258→                    } else {
   259→                        should_swap = char_at(cmp_val, 0) < char_at(key_val, 0);
   260→                    }
   261→                } else if asc {
   262→                    should_swap = len(cmp_val) > len(key_val);
   263→                }
   264→                if !should_swap {
   265→                    break;
   266→                }
   267→                indices[j + 1] = indices[j];
   268→                j = j - 1;
   269→            }
   270→            indices[j + 1] = key_idx;
   271→        }
   272→    }
   273→
   274→    // === 쿼리 실행 ===
   275→
   276→    func execute(t: schema.Table, q: Query) -> QueryResult {
   277→        let result = QueryResult{
   278→            row_indices: make([i32], MAX_RESULT_ROWS),
   279→            row_count:   0,
   280→            agg_value:   0,
   281→            error_code:  QUERY_OK,
   282→        };
   283→
   284→        // 1단계: WHERE 필터링
   285→        let candidates = make([i32], MAX_RESULT_ROWS);
   286→        let candidate_count = 0;
   287→        let i = 0;
   288→        for i = 0; i < t.row_count; i = i + 1 {
   289→            if !t.is_alive(i) {
   290→                continue;
   291→            }
   292→            if eval_where(t, i, q.wheres, q.where_count) {
   293→                if candidate_count < MAX_RESULT_ROWS {
   294→                    candidates[candidate_count] = i;
   295→                    candidate_count = candidate_count + 1;
   296→                }
   297→            }
   298→        }
   299→
   300→        // 2단계: 정렬 (ORDER BY)
   301→        if q.has_order {
   302→            if q.order_by.is_str {
   303→                sort_by_str(t, candidates, candidate_count, q.order_by.col_idx, q.order_by.asc);
   304→            } else {
   305→                sort_by_int(t, candidates, candidate_count, q.order_by.col_idx, q.order_by.asc);
   306→            }
   307→        }
   308→
   309→        // 3단계: OFFSET + LIMIT 적용
   310→        let start = q.offset;
   311→        let end = start + q.limit;
   312→        if end > candidate_count {
   313→            end = candidate_count;
   314→        }
   315→
   316→        for i = start; i < end; i = i + 1 {
   317→            result.row_indices[result.row_count] = candidates[i];
   318→            result.row_count = result.row_count + 1;
   319→        }
   320→
   321→        // 4단계: 집계
   322→        if q.agg_type == AGG_COUNT {
   323→            result.agg_value = i64(candidate_count);
   324→        } else if q.agg_type == AGG_SUM {
   325→            let sum: i64 = 0;
   326→            for i = 0; i < candidate_count; i = i + 1 {
   327→                sum = sum + t.get_int_val(candidates[i], q.agg_col);
   328→            }
   329→            result.agg_value = sum;
   330→        } else if q.agg_type == AGG_MAX {
   331→            if candidate_count > 0 {
   332→                let max_val = t.get_int_val(candidates[0], q.agg_col);
   333→                for i = 1; i < candidate_count; i = i + 1 {
   334→                    let v = t.get_int_val(candidates[i], q.agg_col);
   335→                    if v > max_val {
   336→                        max_val = v;
   337→                    }
   338→                }
   339→                result.agg_value = max_val;
   340→            }
   341→        } else if q.agg_type == AGG_MIN {
   342→            if candidate_count > 0 {
   343→                let min_val = t.get_int_val(candidates[0], q.agg_col);
   344→                for i = 1; i < candidate_count; i = i + 1 {
   345→                    let v = t.get_int_val(candidates[i], q.agg_col);
   346→                    if v < min_val {
   347→                        min_val = v;
   348→                    }
   349→                }
   350→                result.agg_value = min_val;
   351→            }
   352→        }
   353→
   354→        return result;
   355→    }
   356→
   357→    // === 헬퍼 ===
   358→
   359→    func result_row_count(r: QueryResult) -> i32 {
   360→        return r.row_count;
   361→    }
   362→
   363→    func result_agg(r: QueryResult) -> i64 {
   364→        return r.agg_value;
   365→    }
   366→
   367→    // === 헬퍼 함수 ===
   368→
   369→    @inline
   370→    func i32_to_str(n: i32) -> string {
   371→        if n == 0 { return "0"; }
   372→        if n == 1 { return "1"; }
   373→        if n == 2 { return "2"; }
   374→        if n == 3 { return "3"; }
   375→        if n == 4 { return "4"; }
   376→        if n == 5 { return "5"; }
   377→        if n == 6 { return "6"; }
   378→        if n == 7 { return "7"; }
   379→        if n == 8 { return "8"; }
   380→        if n == 9 { return "9"; }
   381→        if n < 0 { return "-" + i32_to_str(-n); }
   382→        let d = n / 10;
   383→        let r = n % 10;
   384→        return i32_to_str(d) + i32_to_str(r);
   385→    }
   386→
   387→    @inline
   388→    func i64_to_str(n: i64) -> string {
   389→        if n == 0 { return "0"; }
   390→        if n < 0 { return "-" + i64_to_str(-n); }
   391→        return i32_to_str(i32(n));
   392→    }
   393→}
