// ============================================================================
// FreeLang QuerySession 모듈 - 세션 기반 다중 쿼리 관리
// ============================================================================
// 목표: 세션 내에서 여러 쿼리를 실행하고 히스토리를 추적
// 원리:
//   1. QuerySession: 고유 세션 ID + 쿼리 실행 엔진 + 히스토리 배열
//   2. QueryHistory: SQL문 + 결과 행 수 + 실행 성공 여부 + 타임스탐프
//   3. 히스토리 관리: 원형 버퍼 패턴 (최대 32개 유지)
// 구조:
//   - 상수 정의 (에러 코드, 제한값)
//   - QueryHistory, QuerySession 구조체
//   - 세션 생성 및 관리 함수 (new, execute, clear_history)
//   - 히스토리 조회 함수 (get_history, get_total, last_query)
//   - 메타데이터 함수 (stats)
// ============================================================================

module query_session {
    // === 에러 코드 ===
    const QSESS_OK:           i32 = 0;
    const QSESS_ERR_FULL:     i32 = 180;
    const QSESS_ERR_NOTFOUND: i32 = 181;

    // === 제한값 ===
    const MAX_QUERY_HISTORY: i32 = 32;

    // === 데이터 구조체 ===

    // 쿼리 히스토리 항목
    struct QueryHistory {
        sql:        string;
        result_cnt: i32;
        exec_ok:    bool;
        ts:         i64;
    }

    // 쿼리 세션
    struct QuerySession {
        session_id:     i64;
        history:        [QueryHistory];
        hist_count:     i32;
        total_queries:  i32;
        runner:         query.Query;
    }

    // === 세션 생성 ===

    // 새로운 세션 생성
    func query_session_new(session_id: i64) -> QuerySession {
        return QuerySession{
            session_id:     session_id,
            history:        make([QueryHistory], MAX_QUERY_HISTORY),
            hist_count:     0,
            total_queries:  0,
            runner:         query.Query{
                table_ptr:   0,
                wheres:      make([query.WhereClause], query.MAX_WHERE),
                where_count: 0,
                order_by:    query.OrderBy{ col_idx: 0, asc: true, is_str: false },
                has_order:   false,
                limit:       query.MAX_RESULT_ROWS,
                offset:      0,
                agg_type:    query.AGG_NONE,
                agg_col:     0,
            },
        };
    }

    // === 쿼리 실행 및 히스토리 기록 ===

    // 쿼리 실행 및 히스토리 추가
    func (sess: *QuerySession) query_session_execute(t: schema.Table, sql: string) -> i32 {
        // 히스토리 오버플로우 체크
        if sess.hist_count >= MAX_QUERY_HISTORY {
            return QSESS_ERR_FULL;
        }

        // 쿼리 엔진 실행
        let result = query.execute(t, sess.runner);

        // 타임스탐프 생성 (간단화: total_queries를 타임스탐프처럼 사용)
        let ts = i64(sess.total_queries);

        // 실행 결과 기록
        if result.error_code == query.QUERY_OK {
            sess.history[sess.hist_count] = QueryHistory{
                sql:        sql,
                result_cnt: result.row_count,
                exec_ok:    true,
                ts:         ts,
            };
        } else {
            sess.history[sess.hist_count] = QueryHistory{
                sql:        sql,
                result_cnt: 0,
                exec_ok:    false,
                ts:         ts,
            };
        }

        // 카운터 증가
        sess.hist_count = sess.hist_count + 1;
        sess.total_queries = sess.total_queries + 1;

        return result.error_code;
    }

    // === 결과 조회 ===

    // 마지막 쿼리의 결과 반환
    func (sess: *QuerySession) query_session_get_result() -> query.QueryResult {
        return query.execute(schema.Table{
            schema:        schema.TableSchema{
                name:        "",
                col_defs:    make([schema.ColumnDef], 0),
                col_count:   0,
                primary_key: 0,
            },
            int_cols:      make([i64], 0),
            str_cols:      make([string], 0),
            bool_cols:     make([bool], 0),
            deleted_flags: make([bool], 0),
            row_ids:       make([i64], 0),
            row_count:     0,
            next_id:       0,
        }, sess.runner);
    }

    // === 히스토리 조회 ===

    // 특정 인덱스의 히스토리 조회
    func (sess: *QuerySession) query_session_get_history(idx: i32) -> (QueryHistory, i32) {
        // 인덱스 범위 검증
        if idx < 0 || idx >= sess.hist_count {
            return QueryHistory{
                sql:        "",
                result_cnt: 0,
                exec_ok:    false,
                ts:         0,
            }, QSESS_ERR_NOTFOUND;
        }

        return (sess.history[idx], QSESS_OK);
    }

    // 전체 쿼리 실행 수 반환
    func (sess: *QuerySession) query_session_get_total() -> i32 {
        return sess.total_queries;
    }

    // 마지막 쿼리의 SQL 반환
    func (sess: *QuerySession) query_session_last_query() -> string {
        if sess.hist_count > 0 {
            return sess.history[sess.hist_count - 1].sql;
        }
        return "";
    }

    // === 히스토리 관리 ===

    // 히스토리 초기화
    func (sess: *QuerySession) query_session_clear_history() -> i32 {
        let i = 0;
        for i = 0; i < sess.hist_count; i = i + 1 {
            sess.history[i] = QueryHistory{
                sql:        "",
                result_cnt: 0,
                exec_ok:    false,
                ts:         0,
            };
        }
        sess.hist_count = 0;
        return QSESS_OK;
    }

    // === 메타데이터 ===

    // 세션 통계를 문자열로 반환
    func (sess: *QuerySession) query_session_stats() -> string {
        let session_str = i64_to_str(sess.session_id);
        let total_str = i32_to_str(sess.total_queries);
        let hist_str = i32_to_str(sess.hist_count);

        return "QuerySession {session: " + session_str + ", total_queries: " + total_str + ", history_count: " + hist_str + "}";
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

